//! **Fuel-carrying accessibility** — removing the capstone's `wfuel` premise.
//!
//! `def_eq_fuel_complete_wh3` carries two unsupplied hypotheses: `hiotap3`, and
//! a global
//!
//! ```text
//! wfuel : forall (e : KExpr), wbelow3_plus_acc e -> WhnfFuelReachesWh3 e
//! ```
//!
//! standing in for `whnf_fuel_from_acc`, which has no three-way analogue. The
//! two-way proof convoys on a budget-free `OptionType` step; the three-way step
//! is budget-indexed, and its `wstarved` arm would require searching the budget
//! upward. That search is the non-constructive step — and the tempting repair, a
//! decidability assumption, is the vacuity trap this programme has already
//! fallen into once.
//!
//! # The fix: put the fuel where it belongs
//!
//! `Wh3NormAcc` is `wbelow3_plus_acc` with a `WhnfFuelReachesWh3` field at every
//! node. Then `wfuel` is the **first projection**, not an assumption, and it
//! reconstructs for components because the second field hands back a
//! `Wh3NormAcc` for anything strictly below. Nothing new is assumed that the
//! conjunction did not already assume.
//!
//! The deletion is **local**, which is why it is free: `wfuel` was applied in
//! exactly two places, both inside the single `whnf_fuel_pair_wh3` argument
//! supplying the recursion's common budget. It never crossed the recursion
//! boundary — `recur` closes over the induction hypothesis alone — so no round
//! and not the dispatch ever had a `wfuel`-shaped binder.
//!
//! # Honest accounting
//!
//! `Wh3NormAcc` is genuinely **stronger** than `wbelow3_plus_acc`;
//! `wh3_norm_acc_to_below` certifies the forgetful direction and the arrow does
//! not run backwards. It strengthens in the right direction — completeness for a
//! fuel-based algorithm should assume the algorithm terminates on the terms it
//! is about — but it is a strengthening, not a repackaging.
//!
//! Only the four RECURSIVE rounds needed `_na` variants. The leaf rounds carry
//! no accessibility premise at all, so they are the same theorem under either
//! order and are cited unchanged rather than cloned.
//!
//! `DerivedProved`, empty axiom closures.

use crate::spec::error::SpecError;
use crate::spec::Specification;

impl Specification {
    /// Fuel-carrying accessibility, and the spine over it.
    pub(super) fn add_wh3_norm_acc(&mut self) -> Result<(), SpecError> {
        self.add_inductive(
            SRC_WH3NORMACC,
            "Wh3NormAcc e: e is accessible in the three-way order AND the loop returns on it — hereditarily. wbelow3_plus_acc with a WhnfFuelReachesWh3 field at every node. \\\n\
             \\\n\
             This exists to REMOVE A PREMISE. The capstone previously carried, separately, a global wfuel : forall e, wbelow3_plus_acc e -> WhnfFuelReachesWh3 e, standing in for whnf_fuel_from_acc, which has no three-way analogue: the two-way proof convoys on a budget-free OptionType step, while the three-way step is budget-indexed and its wstarved arm would require searching the budget upward. That search is the non-constructive step, and the tempting repair — a decidability assumption — is the vacuity trap this program has already fallen into once. \\\n\
             \\\n\
             Bundling the fuel into the accessibility witness makes wfuel the FIRST PROJECTION rather than an assumption, and it reconstructs for components because the second field hands back a Wh3NormAcc for anything strictly below. Nothing new is assumed that the conjunction did not already assume. \\\n\
             \\\n\
             It is genuinely STRONGER than wbelow3_plus_acc — wh3_norm_acc_to_below certifies the forgetful direction and the arrow does not run backwards — and it strengthens in the right direction: completeness for a fuel-based algorithm should assume the algorithm terminates on the terms it is about. Census-neutral.",
        )?;
        self.add_recursive_def(
            SRC_WH3_NORM_ACC_FUEL,
            "wh3_norm_acc_fuel: the first projection — the fuel witness carried at the root. This is exactly the statement that used to be the standalone `wfuel` premise, now a theorem about the hypothesis rather than a second hypothesis beside it. DerivedProved, zero axiom_deps.",
        )?;
        self.add_recursive_def(
            SRC_WH3_NORM_ACC_INV,
            "wh3_norm_acc_inv: the second projection — everything strictly below is itself Wh3NormAcc. What makes the bundle reconstruct across the recursion, which the standalone wfuel could only do by being global. DerivedProved, zero axiom_deps.",
        )?;
        self.add_recursive_def(
            SRC_WH3_NORM_ACC_TO_BELOW,
            "wh3_norm_acc_to_below: the forgetful map to plain accessibility. It certifies that the new premise is at least as strong as the one it replaces, and lets anything still phrased over wbelow3_plus_acc be fed from a Wh3NormAcc. The converse does NOT hold, and that asymmetry is the honest content of the swap. DerivedProved, zero axiom_deps.",
        )?;
        self.add_recursive_def(
            SRC_WHNF_COMPONENT_NORM_ACC_WH3,
            "whnf_component_norm_acc_wh3: an immediate subexpression of a three-way whnf result inherits Wh3NormAcc. The fuel-carrying analogue of whnf_component_acc_wh3, and the reason the rounds below can descend without a global fuel assumption. DerivedProved, zero axiom_deps.",
        )?;
        self.add_recursive_def(
            SRC_DEF_EQ_ROUND_WH3_PROJ_NA,
            "def_eq_round_wh3_proj_na: the proj round, over the fuel-carrying accessibility. Identical to def_eq_round_wh3_proj except that its accessibility premise is Wh3NormAcc rather than wbelow3_plus_acc, so the recursion hands each component a witness that already contains its own fuel. DerivedProved, zero axiom_deps.",
        )?;
        self.add_recursive_def(
            SRC_DEF_EQ_ROUND_WH3_PI_NA,
            "def_eq_round_wh3_pi_na: the pi round, over the fuel-carrying accessibility. Identical to def_eq_round_wh3_pi except that its accessibility premise is Wh3NormAcc rather than wbelow3_plus_acc, so the recursion hands each component a witness that already contains its own fuel. DerivedProved, zero axiom_deps.",
        )?;
        self.add_recursive_def(
            SRC_DEF_EQ_ROUND_WH3_LAM_NA,
            "def_eq_round_wh3_lam_na: the lam round, over the fuel-carrying accessibility. Identical to def_eq_round_wh3_lam except that its accessibility premise is Wh3NormAcc rather than wbelow3_plus_acc, so the recursion hands each component a witness that already contains its own fuel. DerivedProved, zero axiom_deps.",
        )?;
        self.add_recursive_def(
            SRC_DEF_EQ_ROUND_WH3_APP_NA,
            "def_eq_round_wh3_app_na: the app round, over the fuel-carrying accessibility. Identical to def_eq_round_wh3_app except that its accessibility premise is Wh3NormAcc rather than wbelow3_plus_acc, so the recursion hands each component a witness that already contains its own fuel. DerivedProved, zero axiom_deps.",
        )?;
        self.add_recursive_def(
            SRC_DEF_EQ_DISPATCH_WH3_NA,
            "def_eq_dispatch_wh3_na: the dispatch, over the fuel-carrying accessibility. \\\n\
             \\\n\
             Its four LEAF rounds are the already-registered def_eq_round_wh3_{sort,lit,bvar,const}, cited unchanged rather than cloned: those rounds have nothing to recurse into, so they carry no accessibility premise at all and are literally the same theorem under either order. Only the four recursive rounds needed _na variants. DerivedProved, zero axiom_deps.",
        )?;
        self.add_recursive_def(
            SRC_DEF_EQ_FUEL_COMPLETE_WH3_NA,
            "def_eq_fuel_complete_wh3_na: THE CAPSTONE, with one fewer open premise. \\\n\
             \\\n\
             def_eq_fuel_complete_wh3 carries TWO unsupplied hypotheses: hiotap3, and a global wfuel : forall e, wbelow3_plus_acc e -> WhnfFuelReachesWh3 e. This carries only hiotap3. wfuel is gone because the fuel now travels inside the accessibility witness, where it belongs, and is recovered by wh3_norm_acc_fuel. \\\n\
             \\\n\
             The deletion is LOCAL, which is why it costs nothing: wfuel was applied in exactly two places, both inside the single whnf_fuel_pair_wh3 argument that supplies the recursion's common budget. It never crossed the recursion boundary — recur closes over the induction hypothesis alone — so no round and not the dispatch ever had a wfuel-shaped binder to remove. \\\n\
             \\\n\
             WHAT REMAINS OPEN, and it is now one thing plus a residual: hiotap3, inherited debt identical in shape to the two-way hiota and never discharged there either; and the application residual inside hnf3, supplied for the entire rigid-headed class and open for a major stuck for a non-rigid reason. The accessibility premise itself is permanently a hypothesis — total inhabitation is strong normalisation, which is FALSE for this calculus as reflected — so carrying it is the correct shape for the theorem, not a gap in it. \\\n\
             \\\n\
             SCOPE is unchanged and must travel with any public statement: complete against DefEq, which has no eta, no proof irrelevance, no structure-eta, no universe conversion and no literal computation, all of which the shipping is_def_eq implements. Conditional theorem, never an axiom. DerivedProved, zero axiom_deps.",
        )?;
        self.add_recursive_def(
            SRC_DEF_EQ_FUEL_COMPLETE_WH3_AT_THE_RED_ENV_NA,
            "def_eq_fuel_complete_wh3_at_the_red_env_na: the reduced capstone with i1..i8 discharged positionally by the eight the_red_env_*_via_checker witnesses. Premises down to hiotap3, hnf3, and one Wh3NormAcc. DerivedProved, zero axiom_deps.",
        )?;
        Ok(())
    }
}

const SRC_WH3NORMACC: &str = "inductive Wh3NormAcc : KExpr -> Type\n\
             | intro : forall (e : KExpr), WhnfFuelReachesWh3 e -> (forall (e2 : KExpr), wbelow3_plus e2 e -> Wh3NormAcc e2) -> Wh3NormAcc e";

const SRC_WH3_NORM_ACC_FUEL: &str = "def wh3_norm_acc_fuel (e : KExpr) (h : Wh3NormAcc e) : WhnfFuelReachesWh3 e := Wh3NormAcc.rec (fun (x : KExpr) (_h : Wh3NormAcc x) => WhnfFuelReachesWh3 x) (fun (x : KExpr) (hw : WhnfFuelReachesWh3 x) (_hfield : forall (e2 : KExpr), wbelow3_plus e2 x -> Wh3NormAcc e2) (_ih : forall (e2 : KExpr), wbelow3_plus e2 x -> WhnfFuelReachesWh3 e2) => hw) e h";

const SRC_WH3_NORM_ACC_INV: &str = "def wh3_norm_acc_inv (e : KExpr) (h : Wh3NormAcc e) : forall (e2 : KExpr), wbelow3_plus e2 e -> Wh3NormAcc e2 := Wh3NormAcc.rec (fun (x : KExpr) (_h : Wh3NormAcc x) => forall (e2 : KExpr), wbelow3_plus e2 x -> Wh3NormAcc e2) (fun (x : KExpr) (_hw : WhnfFuelReachesWh3 x) (hfield : forall (e2 : KExpr), wbelow3_plus e2 x -> Wh3NormAcc e2) (_ih : forall (e2 : KExpr), wbelow3_plus e2 x -> forall (e3 : KExpr), wbelow3_plus e3 e2 -> Wh3NormAcc e3) => hfield) e h";

const SRC_WH3_NORM_ACC_TO_BELOW: &str = "def wh3_norm_acc_to_below (e : KExpr) (h : Wh3NormAcc e) : wbelow3_plus_acc e := Wh3NormAcc.rec (fun (x : KExpr) (_h : Wh3NormAcc x) => wbelow3_plus_acc x) (fun (x : KExpr) (_hw : WhnfFuelReachesWh3 x) (_hfield : forall (e2 : KExpr), wbelow3_plus e2 x -> Wh3NormAcc e2) (ih : forall (e2 : KExpr), wbelow3_plus e2 x -> wbelow3_plus_acc e2) => wbelow3_plus_acc.intro x ih) e h";

const SRC_WHNF_COMPONENT_NORM_ACC_WH3: &str = "def whnf_component_norm_acc_wh3 (n : Nat) (a : KExpr) (r : KExpr) (c : KExpr) (hr : Eq (OptionType KExpr) (whnf_fuel_red_wh3 the_red_env n a) (OptionType.some KExpr r)) (hc : subexpr_step c r) (hacc : Wh3NormAcc a) : Wh3NormAcc c := wh3_norm_acc_inv a hacc c (wbelow3_plus_of_step_rtc c r a (wbelow3.sub c r hc) (whnf_fuel_red_wh3_wbelow3_rtc n a r hr))";

